import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { main } from "../src/cli/diagrams.js";
import { DIAGRAMS } from "../src/diagram-list.js";
import type { Diagram } from "../src/diagrams.js";
import { gitIn } from "../src/git.js";
import { writeText, writeWorkspace } from "./support/workspace.js";

const OPEN =
  "<!-- diagram:packages generated by pnpm diagrams:generate, never edit by hand -->";
const CLOSE = "<!-- /diagram:packages -->";

/** The packages diagram's region for a workspace of one package, `solo`. */
const REGION =
  `${OPEN}\n\n` +
  "```mermaid\n" +
  "flowchart LR\n" +
  "  %% diagram: packages\n" +
  "  %% Generated from each workspace package's dependencies and peerDependencies; devDependencies are left out.\n" +
  '  subgraph published["Published packages"]\n' +
  '    solo["solo"]\n' +
  "  end\n" +
  '  subgraph private["Private packages"]\n' +
  "  end\n" +
  '  map_project(["Map project"])\n' +
  '  template(["Template: phmilk/reforged-ts-template"])\n' +
  '  map_project -->|"starts from"| template\n' +
  '  template -->|"builds every release before it is published (Template gate)"| published\n' +
  "```\n\n" +
  CLOSE;

/** A git repository: a workspace of one package and a README of `readme`. */
async function repository(readme: string): Promise<string> {
  const root = await writeWorkspace([{ dir: "packages/solo", name: "solo" }]);
  await gitIn(root)(["init", "--quiet"]);
  await writeText(root, "README.md", readme);
  return root;
}

async function runCli(
  root: string,
  args: string[],
  diagrams: readonly Diagram[] = DIAGRAMS,
) {
  let stdout = "";
  let stderr = "";
  const status = await main(
    args,
    {
      stdout: (text) => (stdout += text),
      stderr: (text) => (stderr += text),
    },
    { root, diagrams },
  );
  return { status, stdout, stderr };
}

const readme = (root: string) => readFile(join(root, "README.md"), "utf8");

describe("diagrams:generate", () => {
  it("writes each region and leaves the prose around it as it was", async () => {
    const root = await repository(
      `# Fixture\n\n## Map\n\n<!-- diagram:packages -->\n${CLOSE}\n\nThe prose.\n`,
    );

    expect(await runCli(root, ["generate"])).toEqual({
      status: 0,
      stdout: "Wrote README.md.\n",
      stderr: "",
    });
    expect(await readme(root)).toBe(
      `# Fixture\n\n## Map\n\n${REGION}\n\nThe prose.\n`,
    );
    expect(await runCli(root, ["generate"])).toEqual({
      status: 0,
      stdout: "No file changed: 1 region is what the generator writes.\n",
      stderr: "",
    });
  });

  it("writes nothing when a region is missing or unknown", async () => {
    const text =
      "# Fixture\n\n<!-- diagram:retired -->\n<!-- /diagram:retired -->\n";
    const root = await repository(text);

    expect(await runCli(root, ["generate"])).toEqual({
      status: 1,
      stdout: "",
      stderr:
        "Diagrams: 2 problems the generator cannot fix, so it wrote nothing.\n\n" +
        "- [ ] README.md: a region of the diagram retired, which no diagram of `pnpm diagrams:generate` writes. Remove it, or add the diagram to release/src/diagram-list.ts.\n" +
        "- [ ] README.md: no region for the diagram packages. Add the lines `<!-- diagram:packages -->` and `<!-- /diagram:packages -->` where it belongs, then run `pnpm diagrams:generate`.\n",
    });
    expect(await readme(root)).toBe(text);
  });
});

describe("diagrams:check", () => {
  it("passes when every region is what the generator writes", async () => {
    const root = await repository(`# Fixture\n\n${REGION}\n`);

    expect(await runCli(root, ["check"])).toEqual({
      status: 0,
      stdout:
        "Diagrams match: 1 region is exactly what `pnpm diagrams:generate` writes.\n",
      stderr: "",
    });
  });

  it("fails on a region changed by hand, naming the command that fixes it, and writes nothing", async () => {
    const text = `# Fixture\n\n${REGION.replace('solo["solo"]', 'solo["renamed"]')}\n`;
    const root = await repository(text);

    expect(await runCli(root, ["check"])).toEqual({
      status: 1,
      stdout: "",
      stderr:
        "Diagrams drift: 1 problem. Run `pnpm diagrams:generate` and commit the result.\n\n" +
        "- [ ] README.md: the region of the diagram packages differs from what `pnpm diagrams:generate` writes.\n",
    });
    expect(await readme(root)).toBe(text);
  });

  it("fails on a package added without regenerating", async () => {
    const root = await repository(`${REGION}\n`);
    await writeText(
      root,
      "pnpm-workspace.yaml",
      "packages:\n  - packages/solo\n  - packages/other\n",
    );
    await writeText(
      root,
      "packages/other/package.json",
      JSON.stringify({ name: "other", version: "1.0.0", private: true }),
    );

    expect((await runCli(root, ["check"])).stderr).toContain(
      "README.md: the region of the diagram packages differs",
    );
  });

  it("fails on a missing and an unknown region", async () => {
    const root = await repository(
      "<!-- diagram:retired -->\n<!-- /diagram:retired -->\n",
    );

    expect(await runCli(root, ["check"])).toEqual({
      status: 1,
      stdout: "",
      stderr:
        "Diagrams drift: 2 problems. Run `pnpm diagrams:generate` and commit the result.\n\n" +
        "- [ ] README.md: a region of the diagram retired, which no diagram of `pnpm diagrams:generate` writes. Remove it, or add the diagram to release/src/diagram-list.ts.\n" +
        "- [ ] README.md: no region for the diagram packages. Add the lines `<!-- diagram:packages -->` and `<!-- /diagram:packages -->` where it belongs, then run `pnpm diagrams:generate`.\n",
    });
  });
});

describe("the diagrams CLI", () => {
  it("prints its usage on anything but generate or check", async () => {
    const root = await repository("");

    for (const args of [[], ["write"], ["check", "--root"]]) {
      expect(await runCli(root, args)).toEqual({
        status: 2,
        stdout: "",
        stderr: "Usage: diagrams generate|check\n",
      });
    }
  });
});
